<?php
declare(strict_types=1); namespace Theobroma\OneC\Admin;
use Theobroma\OneC\Ozon\{OzonMatchService,OzonTableParser};
final class OzonImportPage {private const PREVIEW='theobroma_1c_ozon_preview_';public function register():void{add_action('admin_post_theobroma_1c_ozon_preview',[$this,'preview']);add_action('admin_post_theobroma_1c_ozon_apply',[$this,'apply']);}public function preview():void{$this->guard('theobroma_1c_ozon_preview');$file=$_FILES['ozon_file']??null;if(!is_array($file)||($file['size']??0)>5*1024*1024)wp_die('Invalid file',400);$rows=(new OzonTableParser())->parse((string)file_get_contents((string)$file['tmp_name']));$matcher=new OzonMatchService([$this,'lookup']);$preview=[];foreach($rows as$i=>$row){$match=$matcher->match($row);$preview[]=['row'=>$row,'status'=>$match->status,'product_id'=>$match->productId];}set_transient(self::PREVIEW.get_current_user_id(),$preview,30*MINUTE_IN_SECONDS);wp_safe_redirect(admin_url('admin.php?page=theobroma-1c&ozon_preview=1'));exit;}public function apply():void{$this->guard('theobroma_1c_ozon_apply');$preview=get_transient(self::PREVIEW.get_current_user_id());if(!is_array($preview))wp_die('Preview expired',400);$manual=array_map('absint',(array)($_POST['product_id']??[]));$applied=0;foreach($preview as$i=>$item){$row=$item['row']??null;if(!$row instanceof \Theobroma\OneC\Ozon\OzonRow||!$row->valid)continue;$productId=(int)($item['product_id']??0);if($productId<1)$productId=(int)($manual[$i]??0);$product=wc_get_product($productId);if(!$product instanceof \WC_Product)continue;$product->update_meta_data('_theobroma_client_article',$row->clientArticle);$product->update_meta_data('_theobroma_ozon_product_id',$row->ozonProductId);$product->update_meta_data('_theobroma_ozon_sku',$row->ozonSku);$product->update_meta_data('_theobroma_ean',$row->ean);$product->save();$applied++;}delete_transient(self::PREVIEW.get_current_user_id());wp_safe_redirect(add_query_arg('ozon_applied',$applied,admin_url('admin.php?page=theobroma-1c')));exit;}/** @return list<int> */public function lookup(string$field,string$value):array{$meta=['ozon_sku'=>'_theobroma_ozon_sku','ozon_product_id'=>'_theobroma_ozon_product_id','ean'=>'_theobroma_ean'][$field];return array_map('intval',get_posts(['post_type'=>['product','product_variation'],'post_status'=>'any','fields'=>'ids','numberposts'=>2,'meta_key'=>$meta,'meta_value'=>$value]));}public static function previewData():array{$value=get_transient(self::PREVIEW.get_current_user_id());return is_array($value)?$value:[];}private function guard(string$action):void{if(!current_user_can('manage_woocommerce'))wp_die('Forbidden',403);check_admin_referer($action);}}
